<div class="page-head"><div><h1>E-mail</h1><div class="sub">Schránka <b><?=\App\Core\View::e($mailbox['display_name'])?></b> · <?=\App\Core\View::e($mailbox['localpart'])?>@<?=\App\Core\View::e(\App\Services\MailboxService::domain())?></div></div><a class="btn primary" href="#compose">+ Nový e-mail</a></div><div class="card tablewrap"><table class="table"><tr><th>Datum</th><th>Směr</th><th>Od</th><th>Komu</th><th>Předmět</th><th>Přílohy</th></tr><?php foreach($rows as $r):?><tr><td><?=\App\Core\View::e(date('d.m.Y H:i',strtotime($r['created_at'])))?></td><td><?=($r['direction']==='inbound'?'Přijatý':'Odeslaný')?></td><td><?=\App\Core\View::e($r['from_email'])?></td><td><?=\App\Core\View::e($r['to_email'])?></td><td><a href="/mail/<?=$r['id']?>"><b><?=\App\Core\View::e($r['subject'])?></b></a></td><td><?=((int)$r['attachment_count'])?:''?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="sub">Schránka je zatím prázdná.</td></tr><?php endif;?></table></div><div class="card" id="compose" style="margin-top:16px"><h3>Nový e-mail</h3><form class="form" method="post" action="/mail/send" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="field"><label>Komu</label><input type="email" name="to" required></div><div class="field"><label>Předmět</label><input name="subject" required></div><div class="field"><label>Zpráva</label><textarea name="body" rows="9" required></textarea></div><div class="field"><label>Přílohy</label><input type="file" name="attachments[]" multiple></div><button class="btn primary">Odeslat z <?=\App\Core\View::e($mailbox['localpart'])?>@<?=\App\Core\View::e(\App\Services\MailboxService::domain())?></button></form></div>